package com.shopsphere.controller; import com.shopsphere.model.User;import com.shopsphere.service.UserService;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;@WebServlet("/register") public class RegisterServlet extends HttpServlet{private final UserService s=new UserService();protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{try{User u=new User();u.setName(r.getParameter("name"));u.setEmail(r.getParameter("email"));u.setPassword(r.getParameter("password"));u.setMobile(r.getParameter("mobile"));p.sendRedirect(r.getContextPath()+(s.register(u)?"/login.jsp?registered=1":"/register.jsp?error=Email+exists"));}catch(Exception e){throw new IOException(e);}}}
